export class DelegationsPanel {
  protected readonly delegations = inject(Delegations);
  private readonly sheets = inject(Sheets);

  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);
  protected readonly form = new FormGroup({
    user: new FormControl('', { nonNullable: true }),
    from: new FormControl('', { nonNullable: true }),
    to: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    // Each (re)load of a sheet re-reads its delegations from the store.
    toObservable(this.sheets.loaded)
      .pipe(
        switchMap((sheet) => {
          this.error.set(null);
          return this.delegations.load(sheet?.id ?? null) ?? EMPTY;
        }),
        takeUntilDestroyed(),
      )
      .subscribe({ error: () => this.error.set('Could not read the delegations.') });
    // An error is removed as soon as its form is changed.
    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.error.set(null));
  }

  protected delegate(): void {
    // A second submit before the first has answered is ignored, so it stores one delegation.
    if (this.saving()) return;
    this.error.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const user = this.form.controls.user.value.trim();
    const from = this.form.controls.from.value.trim();
    const to = this.form.controls.to.value.trim();
    if (!user) {
      this.error.set('Type the user name to delegate the steward role to.');
      return;
    }
    if ((from && !DATE_PATTERN.test(from)) || (to && !DATE_PATTERN.test(to))) {
      this.error.set('Type each date as yyyy-mm-dd, or leave it blank for the sheet\'s today.');
      return;
    }
    this.saving.set(true);
    this.delegations.delegate(sheet.id, { user, from: from || null, to: to || null }).subscribe({
      next: () => {
        this.saving.set(false);
        this.form.reset({ user: '', from: '', to: '' }, { emitEvent: false });
      },
      error: () => {
        this.saving.set(false);
        this.error.set('Could not delegate: only a steward can, and the to-date must not be before the from-date.');
      },
    });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, tap } from 'rxjs';

/** A steward's delegation of the steward role to a user, from a from-date to a to-date, inclusive. */
export interface DelegationView {
  id: number;
  user: string;
  by: string;
  from: string;
  to: string;
}

/** A delegation as the form submits it; a blank date is the sheet's today. */
export interface DelegationForm {
  user: string;
  from: string | null;
  to: string | null;
}

// The steward role's delegations on the active sheet, in the order they were made.
@Injectable({ providedIn: 'root' })
export class Delegations {
  private readonly http = inject(HttpClient);
  private readonly list = signal<DelegationView[]>([]);
  readonly all = this.list.asReadonly();

  /** Re-read a sheet's delegations from the store; null clears them. */
  load(sheetId: string | null): Observable<DelegationView[]> | null {
    this.list.set([]);
    if (sheetId === null) return null;
    return this.http.get<DelegationView[]>(this.base(sheetId)).pipe(tap((list) => this.list.set(list)));
  }

  /** Delegate the steward role; refused unless the signed-in user is a steward and the range runs forward. */
  delegate(sheetId: string, form: DelegationForm): Observable<DelegationView> {
    return this.http
      .post<DelegationView>(this.base(sheetId), form)
      .pipe(tap((saved) => this.list.update((list) => [...list, saved])));
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/delegations`;
  }
}
